#include <iostream>
using namespace std;

// class 把「数据」和「操作数据的函数」打包在一起
class Point {
public:                 // 不写 public: 的话，下面这些默认是私有的，外面用不了
    int x;              // 成员变量
    int y;

    // 成员函数直接写在类里，不需要写 Point:: 前缀
    void show() {
        cout << x << " " << y << endl;
    }
};                      // ← 类的定义末尾必须有分号！

int main() {
    int a, b;
    cin >> a >> b;

    Point p;            // 创建一个对象（此时 x、y 还是内存里的残留值）
    p.x = a;            // 用点号 . 访问成员变量
    p.y = b;
    p.show();           // 用点号 . 调用成员函数

    return 0;
}

