#include <iostream>
using namespace std;

class Rectangle {
private:                    // 宽高设成私有，外面只能通过成员函数使用
    int w;
    int h;

public:
    // 构造函数：名字和类名相同，没有返回值类型
    Rectangle(int width, int height) {
        w = width;
        h = height;
    }

    int area() {
        return w * h;
    }

    int perimeter() {
        return 2 * (w + h);
    }
};

int main() {
    int width, height;
    cin >> width >> height;

    // 创建对象的同时就完成了初始化，不可能得到一个「半成品」矩形
    Rectangle r(width, height);

    cout << r.area() << endl;
    cout << r.perimeter() << endl;
    return 0;
}

