#include <iostream>
using namespace std;

class Student {
private:
    const int id;       // const 成员：出生之后就不能再赋值了
    int score;

public:
    // 冒号后面是初始化列表：用参数 i 初始化 id，用参数 s 初始化 score
    Student(int i, int s) : id(i), score(s) {
        // 函数体里做剩下的收尾工作；这里没有别的事可做
    }

    void addScore(int d) {
        score += d;     // score 不是 const，可以随便改
        // id += d;     // ← 如果写这一行，编译直接报错
    }

    void show() {
        cout << id << endl;
        cout << score << endl;
    }
};

int main() {
    int id, s, d;
    cin >> id >> s >> d;

    Student stu(id, s);
    stu.addScore(d);
    stu.show();
    return 0;
}

