#include <iostream>
#include <string>
using namespace std;

class Life {
private:
    string name;

public:
    // 构造函数：对象出生时自动调用
    Life(string n) : name(n) {
        cout << "create " << name << endl;
    }

    // 析构函数：名字是 ~类名，没有参数、没有返回值，也不能重载
    ~Life() {
        cout << "destroy " << name << endl;
    }

    void hello() {
        cout << "hello " << name << endl;
    }
};

int main() {
    int n;
    cin >> n;

    Life a("A");

    for (int i = 0; i < n; i++) {
        Life t("T");    // 每轮循环进入时构造
        t.hello();
    }                   // ← 每轮循环一结束，t 立刻在这里被析构

    a.hello();
    return 0;
}   // ← main 结束时，a 才被析构，输出最后一行 destroy A

