#include <iostream>
using namespace std;

class Account {
private:
    int balance;        // 私有：类外不能直接读写，只能走下面的成员函数

public:
    Account(int b) {
        balance = b;
    }

    void deposit(int amount) {
        balance += amount;
    }

    // 返回 true 表示取款成功，false 表示余额不足
    bool withdraw(int amount) {
        if (amount > balance) {
            return false;   // 余额不足：一分不动，直接拒绝
        }
        balance -= amount;
        return true;
    }

    int getBalance() {
        return balance;
    }
};

int main() {
    int b, n;
    cin >> b >> n;

    Account acc(b);

    for (int i = 0; i < n; i++) {
        char op;
        int x;
        cin >> op >> x;

        if (op == 'd') {
            acc.deposit(x);
            cout << acc.getBalance() << endl;
        } else {
            if (acc.withdraw(x)) {
                cout << acc.getBalance() << endl;
            } else {
                cout << "fail" << endl;   // 余额不足
            }
        }
    }
    return 0;
}

