#include <iostream>
using namespace std;

class Stat {
private:
    int sum;    // 总和
    int cnt;    // 个数
    int mx;     // 最大值

public:
    Stat();                     // 类里只写声明，末尾是分号
    Stat& push(int v);
    int total() const;          // 注意参数列表后面的 const
    int maximum() const;
    int count() const;
};

// ---- 以下都是类外定义，每个函数前面必须写 Stat:: ----

Stat::Stat() : sum(0), cnt(0), mx(0) {
}

Stat& Stat::push(int v) {
    this->sum += v;             // this 指向调用者，this->sum 就是"这个对象的 sum"
    this->cnt++;
    // 第一个数直接成为最大值；之后只有更大的才会替换
    if (this->cnt == 1 || v > this->mx) {
        this->mx = v;
    }
    return *this;               // 返回对象自己，于是可以链式调用 s.push(1).push(2)
}

// const 成员函数：承诺不修改对象的成员
int Stat::total() const {
    return sum;
}

int Stat::maximum() const {
    return mx;
}

int Stat::count() const {
    return cnt;
}

// 参数是 const 引用：s 是只读的，所以里面只能调用 const 成员函数
void printStat(const Stat& s) {
    cout << s.total() << endl;
    cout << s.maximum() << endl;
    cout << s.count() << endl;
}

int main() {
    int n;
    cin >> n;

    Stat s;
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        s.push(x);              // 也可以写成一串：s.push(1).push(2).push(3);
    }

    printStat(s);
    return 0;
}

tutorial.body:
类里面只写**声明**（函数头加分号），真正的实现搬到类外面去写。这时函数名前面必须加上 `类名::`：

```
class Stat {
public:
    int total() const;      // 类里：只有声明
};

int Stat::total() const {   // 类外：Stat:: 说明这个 total 属于 Stat
    return sum;
}
```

`Stat::total` 里的 `::` 叫**作用域解析运算符**，它告诉编译器「这是 Stat 类的那个 total」，而不是一个碰巧同名的普通函数。

**最容易犯的错**：类外定义时把 `Stat::` 漏了。编译器会把它当成一个全新的普通函数，然后报「`sum` 没有声明」——因为你已经不在类的作用域里了，看不见成员变量。

**第二个坑**：类里的声明和类外的定义必须**完全一致**。`const` 要写两遍，只在一处写会报 `out-of-line definition does not match`。

tutorial.code:
class Stat {
private:
    int sum;
public:
    int total() const;      // 类里：只写声明，以分号结尾
};

// 类外：Stat:: 指明这个 total 属于 Stat 类
int Stat::total() const {
    return sum;
}

// 参数是 const 引用：s 只读
void printStat(const Stat& s) {
    cout << s.total() << endl;    // 只有 const 成员函数能这样调用
    // s.push(1);                 // ❌ 编译错误：push 不是 const 成员函数
}

Stat& Stat::push(int v) {
    this->sum += v;   // this 指向调用者，this->sum 就是这个对象的 sum
    return *this;     // 返回对象自己
}

// 于是可以把调用串起来：
s.push(1).push(2).push(3);
